    xm1: DATA_TYPE
    tm1: DATA_TYPE
    ym1: DATA_TYPE
    ym2: DATA_TYPE
    xp1: DATA_TYPE
    xp2: DATA_TYPE
    tp1: DATA_TYPE
    tp2: DATA_TYPE
    yp1: DATA_TYPE
    yp2: DATA_TYPE

    # Deriche filter coefficients.
    k: DATA_TYPE
    a1: DATA_TYPE
    a2: DATA_TYPE
    a3: DATA_TYPE
    a4: DATA_TYPE
    a5: DATA_TYPE
    a6: DATA_TYPE
    a7: DATA_TYPE
    a8: DATA_TYPE
    b1: DATA_TYPE
    b2: DATA_TYPE
    c1: DATA_TYPE
    c2: DATA_TYPE

