    k = (
        (1.0 - exp(-alpha)) * (1.0 - exp(-alpha))
        / (1.0 + 2.0 * alpha * exp(-alpha) - exp(2.0 * alpha))
    )
    a1 = k
    a5 = k
    a2 = k * exp(-alpha) * (alpha - 1.0)
    a6 = a2
    a3 = k * exp(-alpha) * (alpha + 1.0)
    a7 = a3
    a4 = -k * exp(-2.0 * alpha)
    a8 = a4
    b1 = pow(2.0, -alpha)
    b2 = -exp(-2.0 * alpha)
